const rowsOf = (node) => { try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; } };
const activeClients = () => rowsOf('Read Clients').filter((c) => c.client_id && String(c.status || '').toLowerCase() === 'active');
const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
const daysAgo = (s) => { const t = Date.parse(s); return Number.isNaN(t) ? null : Math.floor((Date.now() - t) / 864e5); };

return activeClients().filter((c) => String(c.ga4_property_id || '').replace(/\D/g, '')).map((c) => ({ json: {
  client: c, ga4_property_id: c.ga4_property_id,
  ga4_request: { dateRanges: [{ startDate: '35daysAgo', endDate: 'yesterday' }], dimensions: [{ name: 'date' }],
    metrics: [{ name: 'sessions' }, { name: 'keyEvents' }, { name: 'totalRevenue' }], orderBys: [{ dimension: { dimensionName: 'date' } }], keepEmptyRows: true },
} }));

const c = $('Prep Daily Series').item.json.client;
const cfg = $('Config').first().json;
const rows = ($json.rows || []).map((r) => ({ date: r.dimensionValues[0].value, sessions: Number(r.metricValues[0].value), keyEvents: Number(r.metricValues[1].value), revenue: Number(r.metricValues[2].value) }))
  .sort((a, b) => a.date.localeCompare(b.date));
const mean = (a) => a.reduce((s, v) => s + v, 0) / (a.length || 1);
const std = (a) => { const m = mean(a); return Math.sqrt(mean(a.map((v) => (v - m) ** 2))); };
const findings = [];
if (rows.length >= 29) {
  const y = rows[rows.length - 1];
  for (const [metric, floor] of [['sessions', cfg.min_baseline_sessions], ['keyEvents', cfg.min_baseline_key_events], ['revenue', 100]]) {
    const sameDay = [8, 15, 22, 29].map((o) => rows[rows.length - o]?.[metric]).filter((v) => v !== undefined);
    const prior = rows.slice(-29, -1).map((r) => r[metric]);
    const base = mean(sameDay); const sd = std(prior); const val = y[metric];
    if (base < Number(floor)) continue;
    const change = ((val - base) / base) * 100; const z = sd ? (val - mean(prior)) / sd : (val === mean(prior) ? 0 : Math.sign(val - mean(prior)) * 99);
    if (Math.abs(change) >= Number(cfg.threshold_pct) && Math.abs(z) >= Number(cfg.min_z)) {
      findings.push({ metric, date: y.date, value: val, same_weekday_baseline: Math.round(base * 100) / 100, change_pct: Math.round(change * 10) / 10, z_score: Math.round(z * 10) / 10, direction: change < 0 ? 'drop' : 'spike' });
    }
  }
}
const schema = { type: 'object', additionalProperties: false, required: ['severity', 'headline', 'likely_causes', 'immediate_actions', 'client_message_draft'],
  properties: { severity: { type: 'string', enum: ['low', 'medium', 'high', 'critical'] }, headline: { type: 'string' },
    likely_causes: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['cause', 'likelihood', 'how_to_check'], properties: { cause: { type: 'string' }, likelihood: { type: 'string', enum: ['high', 'medium', 'low'] }, how_to_check: { type: 'string' } } } },
    immediate_actions: { type: 'array', items: { type: 'string' } }, client_message_draft: { type: 'string' } } };
return { json: { client: c, has_anomaly: findings.length > 0, findings, ga4_error: $json.error ? ($json.error.message || 'GA4 error') : null, brain: {
  skill: 'analytics', caller: 'Anomaly Sentinel', client: c.client_name, effort: 'medium', max_tokens: 5000, schema,
  context: { client: c.client_name, website: c.website, services: c.services, anomalies: findings, last_14_days: rows.slice(-14) },
  task: 'Diagnose these anomalies. Rank the likely causes (tracking or tag breakage, site outage, campaign paused or budget change, algorithm update, seasonality or holiday, bot traffic) and give a concrete way to check each one. A drop to near-zero sessions usually means tracking is broken; say so. Draft a short, calm client message the AM can send if needed.',
} } };

const x = $json; const a = x.ai || {};
const icon = { critical: ':rotating_light:', high: ':red_circle:', medium: ':large_orange_circle:', low: ':large_yellow_circle:' }[a.severity] || ':warning:';
const f = x.findings.map((d) => `• *${d.metric}* ${d.direction} ${d.change_pct}% vs same-weekday avg (${d.value} vs ${d.same_weekday_baseline}, z=${d.z_score}) on ${d.date}`).join('
');
const causes = (a.likely_causes || []).map((c) => `• _${c.likelihood}_ ${c.cause}. Check: ${c.how_to_check}`).join('
');
const acts = (a.immediate_actions || []).map((s, i) => `${i + 1}. ${s}`).join('
');
return { json: { text: `${icon} *${x.client.client_name}: ${a.headline || 'metric anomaly'}* (${a.severity || 'unrated'})
${f}

*Likely causes*
${causes}

*Do now*
${acts}

*Draft client message*
>${String(a.client_message_draft || '').replace(/
/g, '
>')}` } };
